// Guarda cada mensaje del simulador en el jugador que toca, sin traducir nada.
// El topic dice dónde va: lo que hay después de "sensors/" es la ruta dentro de "sensors".
//   p1/sensors/gps                     →  sensors.gps = payload
//   p1/sensors/termometer/temperature  →  sensors.termometer.temperature = payload
const partes = msg.topic.split('/');
const jugadorId = partes[0];
const ruta = partes.slice(2);
if (partes[1] !== 'sensors' || ruta.length === 0 || !/^p\d{1,2}$/.test(jugadorId)) {
    return null;
}
if (typeof msg.payload !== 'object' || msg.payload === null) {
    node.warn('Payload que no es JSON en ' + msg.topic);
    return null;
}

const jugadores = flow.get('jugadores') || {};
const j = jugadores[jugadorId] || { sensors: {}, ultimo: 0 };

let destino = j.sensors;
for (let i = 0; i < ruta.length - 1; i++) {
    destino[ruta[i]] = destino[ruta[i]] || {};
    destino = destino[ruta[i]];
}
destino[ruta[ruta.length - 1]] = msg.payload;
j.ultimo = Date.now();

jugadores[jugadorId] = j;
flow.set('jugadores', jugadores);
node.status({ fill: 'green', shape: 'dot', text: Object.keys(jugadores).length + ' jugador(es)' });
return null;

// Una vez por segundo junta lo que ha llegado de cada jugador en un lote para POST /api/telemetria
// (formato en docs/contratos/api.md).
//   - Un jugador entra en el lote cuando ya tiene gps, accelerometer y pulsemeter.
//     Si le falta alguno (el mensaje llegará en un momento), espera al segundo siguiente.
//   - Watchdog: si un jugador lleva 5 s sin mandar nada, va como "sin_senal".
const SIN_SENAL_MS = 5000;
const OBLIGATORIOS = ['gps', 'accelerometer', 'pulsemeter'];

const jugadores = flow.get('jugadores') || {};
const ahora = Date.now();
const ts = new Date(ahora).toISOString();
const lecturas = [];
let sinSenal = 0;

for (const [jugadorId, j] of Object.entries(jugadores)) {
    if (ahora - j.ultimo > SIN_SENAL_MS) {
        lecturas.push({ jugadorId: jugadorId, ts: ts, estado: 'sin_senal' });
        sinSenal++;
        continue;
    }
    if (OBLIGATORIOS.every(function (s) { return j.sensors[s]; })) {
        lecturas.push({ jugadorId: jugadorId, ts: ts, estado: 'ok', sensors: j.sensors });
        j.sensors = {};
    }
}
flow.set('jugadores', jugadores);

if (lecturas.length === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: 'esperando datos del simulador' });
    return null;
}

const clave = env.get('API_KEY_PASARELA');
if (!clave) {
    node.status({ fill: 'red', shape: 'ring', text: 'falta API_KEY_PASARELA' });
    node.error('Falta la variable de entorno API_KEY_PASARELA: arranca Node-RED con las variables del .env');
    return null;
}

msg.url = (env.get('API_URL') || 'http://localhost:3000') + '/api/telemetria';
msg.headers = { 'Content-Type': 'application/json', 'x-api-key': clave };
msg.payload = { ts: ts, lecturas: lecturas };
node.status({ fill: 'blue', shape: 'dot', text: lecturas.length + ' lectura(s)' + (sinSenal ? ', ' + sinSenal + ' sin señal' : '') });
return msg;

// Muestra en el nodo la respuesta de la API y saca por la salida solo los errores (van al debug)
const codigo = msg.statusCode;
if (codigo === 202) {
    const p = msg.payload || {};
    let texto = '202 · ' + p.recibidas + ' recibidas';
    if (p.ignoradas) texto += ' · ignoradas: ' + p.ignoradas.join(', ');
    node.status({ fill: p.ignoradas ? 'yellow' : 'green', shape: 'dot', text: texto });
    return null;
}
node.status({ fill: 'red', shape: 'dot', text: codigo ? 'error ' + codigo : 'la API no responde' });
return msg;
